#[test]
fn shard_boundary_validates_fabricated_id_before_admission() -> Result<(), Box<dyn std::error::Error>> {
    let journal = std::sync::Arc::new(crate::journal::VolatileRuntimeJournal::new());
    let mut shard = Shard::new_with_journal(
        ShardConfig {
            command_queue_capacity: 64,
            trace_capacity: 64,
            step_budget_per_tick: 4,
            max_active_runs: 8,
            policy: RuntimePolicy::Relaxed,
        },
        journal.clone(),
    );
    let workflow = do_workflow(0)?;
    let run = RunId::new(100);
    let contract = make_contract(999, "fabricated")?;
    let action_contracts: Box<[vb_core::action::ActionContract]> = Box::from([contract]);

    let snapshot = journal.snapshot()?;
    shard.enqueue(ShardCommand::SubmitWithContracts {
        run, workflow, caps: CapabilitySet::empty(), action_contracts,
    })?;
    let tick_result = shard.tick();
    match tick_result {
        Err(RuntimeError::ContractValidationError { action, error }) => {
            assert_eq!(action, ActionId::new(999));
            assert_eq!(error, "contract at index 0 has ID 999 (expected 0)");
        }
        other => return Err(format!("expected Err(ContractValidationError), got: {:?}", other).into()),
    }
    assert!(!shard.run_state_contains(run), "run must not be admitted");
    assert!(!shard.terminal_runs_contains(run), "run must not be terminal");
    let after = journal.snapshot()?;
    assert_eq!(snapshot, after, "journal must be unchanged after validation failure");
    Ok(())
}

